use dioxus::prelude::*;

/// Link one thing wrong with a form to the control it is about.
///
/// # Accessibility
///
/// A real `<a href>`, never a button, so it works with the script blocked and opens in a new tab when a reader asks. The link text is the whole sentence, so listing the page's links lists the complaints.
#[component]
pub fn ErrorSummaryItem(
    /// The id of the control this entry is about, the same id its `Field` was given. **Required**. It becomes `href="#{control}"`, so the link works with the script blocked.
    control: String,
    /// Extra classes for the root element.
    #[props(default)]
    class: String,
    /// The content.
    children: Element,
) -> Element {
    let root = format!("nd-error-summary-item {class}");
    let root = root.trim().to_owned();

    rsx! {
        li { class: "{root}",
            // A REAL LINK TO A REAL ID. It works with the script blocked, it
            // opens in a new tab when a reader asks, and it says where it
            // goes — none of which a button with a handler does.
            a {
                class: "nd-error-summary-link",
                href: "#{control}",
                "data-nd-error-summary-link": "",
                {children}
            }
        }
    }
}
